// LoadUser loads the workoutComment's User into the .R struct
func (o *WorkoutComment) LoadUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.User = nil
	o.R.Loaded.User = false

	related, err := o.User(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.WorkoutComments = WorkoutCommentSlice{o}

	o.R.User = related
	o.R.Loaded.User = true
	return nil
}

// LoadUser loads the workoutComment's User into the .R struct
func (os WorkoutCommentSlice) LoadUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	users, err := os.User(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.User = nil
		o.R.Loaded.User = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	workoutCommentByKey := make(map[string][]*WorkoutComment, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		workoutCommentByKey[o.UserID] = append(workoutCommentByKey[o.UserID], o)
	}

	for _, rel := range users {

		owners, ok := workoutCommentByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.User != nil {
				continue
			}

			rel.R.WorkoutComments = append(rel.R.WorkoutComments, o)

			o.R.User = rel

		}
	}

	return nil
}

